import{_ as e,o as a,c as o,a3 as r}from"./chunks/framework.BWzgKoSO.js";const s="/incomplete-weight-loss-guide/images/creators/shaohui.jpg",p="/incomplete-weight-loss-guide/images/creators/zhang-laoshi.jpg",i="/incomplete-weight-loss-guide/images/creators/baoke.jpg",n="/incomplete-weight-loss-guide/images/creators/ningge.jpg",g="/incomplete-weight-loss-guide/images/creators/tanchengyi.jpg",h="/incomplete-weight-loss-guide/images/creators/zhangsi.jpg",w=JSON.parse('{"title":"附 D　跟着谁看","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/d-who-to-follow.md","filePath":"appendix/d-who-to-follow.md","lastUpdated":1793339289000}'),l={name:"appendix/d-who-to-follow.md"};function c(d,t,m,_,b,f){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="附-d-跟着谁看" tabindex="-1">附 D　跟着谁看 <a class="header-anchor" href="#附-d-跟着谁看" aria-label="Permalink to &quot;附 D　跟着谁看&quot;">​</a></h1><p>先说清楚：<strong>下面这六个人，都是我自己一直在看的。</strong> 不是搜出来凑数的名单，是我手机里真的会点开、有的看了两年多。他们的内容对我很有启发——这本书里好几个判断，追根溯源是从他们那儿来的。</p><p>我得说清楚哪一部分是我的：方法归他们，落到我自己身上怎么用、哪些我试过哪些没试过，是我自己的账。</p><p>判断标准只有一条：他讲的东西最后能不能落回“吃进去的比花出去的少”。落不回去的，再大声也不听。</p><h2 id="b-站" tabindex="-1">B 站 <a class="header-anchor" href="#b-站" aria-label="Permalink to &quot;B 站&quot;">​</a></h2><img src="'+s+'" width="56" height="56" alt="烧毁一切就是美 头像"><p><strong>烧毁一切就是美</strong>　平台：B 站（约 75.9 万粉）　<a href="https://space.bilibili.com/1024129080" target="_blank" rel="noreferrer">主页直达</a></p><p>在日本工作的中国上班族，东京健美公开赛冠军，健身二十多年，本职跟食品安全有关，所以配料表、食品标签这块讲得特别细。三大营养素怎么配、碳水怎么算、动作怎么做，讲得有秩序。他的价值在“为什么”——为什么要这么吃、为什么这么算。</p><p>对我影响最大的一点：他讲每一件事都先讲依据，再讲做法。我后来给这本书的每条结论标证据等级，源头在这里。</p><p>要注意：他是按健美备赛的标准讲的。你不打比赛，不需要那么严。</p><img src="'+p+'" width="56" height="56" alt="心平气和的张老师 头像"><p><strong>心平气和的张老师</strong>　平台：B 站（约 21.5 万粉）　<a href="https://space.bilibili.com/356307984" target="_blank" rel="noreferrer">主页直达</a></p><p>健身科普，美国体能协会注册体能训练专家，国家职业资格认证健身教练，也在大学带健身与体能课。讲训练原理、增肌计划、停训之后肌肉会不会掉，一句一句说，不喊口号。他的价值在“原理”——动作为什么这么做，计划为什么这么排。</p><p>想练力量又怕被“一周速成”带偏的人，适合看他。第四部分那六个自重动作的要点，有不少是照他讲的原理写的。</p><img src="'+i+'" width="56" height="56" alt="宝克力气大 头像"><p><strong>宝克力气大</strong>　平台：B 站（约 17.6 万粉）　<a href="https://space.bilibili.com/44052063" target="_blank" rel="noreferrer">主页直达</a></p><p>大基数的真实记录。从三百二十斤开始减，现在两百八十斤上下，视频里天天讲吃了什么、掉了多少、怎么撑住的。他的价值在“过程”——你能看到一个三百斤的人一个月大概掉多少，中间会遇上什么。</p><p>他让我明白一件事：大基数减重最难的不是方法，是“今天还要不要继续”这件事本身。他的签名写着“别网暴我，我有肥胖症”——这句话我记了很久。</p><p>要注意：这是个人记录，不是方法课。他做对的你能学，他的节奏不一定适合你。</p><h2 id="抖音" tabindex="-1">抖音 <a class="header-anchor" href="#抖音" aria-label="Permalink to &quot;抖音&quot;">​</a></h2><p>抖音的个人主页链接要挂一串账号内部编号，我给不了可核的直链，所以下面写的是<strong>抖音号</strong>——在 App 里搜这个号最准，比搜名字靠谱，同名的太多。</p><img src="'+n+'" width="56" height="56" alt="宁哥有礼 头像"><p><strong>宁哥有礼</strong>　平台：抖音（约 42.9 万粉）</p><p>减脂博主，风格暴躁，讲供能、平台期、皮质醇，成体系，也有成套的课在卖。</p><p>得提一句：他的核心说法是“缺口很小、甚至没有缺口，靠长时间有氧把脂肪烧掉”，这跟这本书“缺口是核心”不一样。我不否认这套练法对他和他带的人有效，但你要是零基础、日常活动量很低，先把缺口做实，再谈别的。他的营养框架和运动安排可以看，结论别全接。</p><img src="'+g+'" width="56" height="56" alt="谭成义 头像"><p><strong>谭成义</strong>　平台：抖音（约 388.5 万粉，抖音号 nishitiantan）</p><p>网上也常写成“谭成毅”，人称谭师。自然古典健美，拿过 IFBB 职业卡，是中国第一个拿到自然古典职业卡的选手。他的减脂计划做得细：按性别、按每周有效运动时长（两三小时、四五小时、六七小时），给出碳水、蛋白质、脂肪各多少克，比如碳水每公斤 2 到 3.5 克。</p><p>适合已经练起来、想把吃法算精确的人。零基础先别钻这个，容易算晕。</p><img src="'+h+'" width="56" height="56" alt="张司 头像"><p><strong>张司</strong>　平台：抖音、小红书（约 55.9 万粉，抖音号 zhangsi007）</p><p>西安人，健身科普，栏目叫“减脂的暴躁小课堂”，说话冲，讲原理也讲心态。他有一句话我认同，也写进了这本书：减肥不是考研，不用把每一样都算到小数点。</p><h2 id="怎么用这份名单" tabindex="-1">怎么用这份名单 <a class="header-anchor" href="#怎么用这份名单" aria-label="Permalink to &quot;怎么用这份名单&quot;">​</a></h2><p><strong>一，看原理的跟看记录的分开。</strong> 张老师、烧毁一切就是美属于前者——他们讲为什么，能迁移到你自己的条件上。宝克力气大属于后者——他给你参照系，让你知道一个真在减的人是什么样。两类都看，但别拿记录当方法。</p><p><strong>二，谁卖课，谁的话就要打折。</strong> 不是说卖课的人讲错，而是他讲什么、不讲什么，会受这门课能不能卖出去影响。打折的办法很简单：他说某件事有用，你去附 E 里找有没有 A 级证据；找不到，就当经验听。</p><p><strong>三，冲突的说法不要急着选边。</strong> 这本书和宁哥有礼就明着不一样。这种时候别问“谁对”，问“对我现在这个阶段，哪一条更能落地”。等你缺口做稳了，再去试他的做法也不迟。</p><p><strong>四，一个人只看一个方向就够了。</strong> 减重这件事的知识量不大，看五六个人、看二十个人，能拿到的还是那些。真正改变的是你每天记不记、走不走、吃多少。名单长不如动作稳。</p><h2 id="我没推荐的" tabindex="-1">我没推荐的 <a class="header-anchor" href="#我没推荐的" aria-label="Permalink to &quot;我没推荐的&quot;">​</a></h2><p>卖代餐、卖酵素、卖“七天瘦十斤”课的一律不在这份名单里。不是因为他们的方法一定无效，而是这类账号的内容和商品绑得太紧，不好分离。</p><p>还有一个提醒：不要照着某个博主的饮食清单买一周的菜。他们的方案是按自己的体重、训练量、生活节奏配的，你直接照抄，最可能的结果是吃不下。</p><hr><p>头像取自他们各自平台的公开头像，只作识别用，不作任何背书。粉丝数是查的时候的数，会变。</p>',42)])])}const k=e(l,[["render",c]]);export{w as __pageData,k as default};
